=== FILE: tb/tb_pwm_pulse_width.v ===
`timescale 1ns / 1ps
// Repro for bucket B1 (pulse_width): the pwm high run must last exactly `duty`
// clock cycles. Checks only high-run length, which is independent of the period.
module tb_pwm_pulse_width;
    reg        clk = 1'b0;
    reg        rst = 1'b1;
    reg  [3:0] duty = 4'd3;
    wire       pwm;
    integer    passed = 0;
    integer    failed = 0;
    integer    guard;
    integer    len;
    integer    i;
    reg        ok;
    reg [8*64-1:0] nonce;

    pwm_gen #(.PERIOD(8)) dut (.clk(clk), .rst(rst), .duty(duty), .pwm(pwm));

    always #5 clk = ~clk;

    task check_eq;
        input integer got;
        input integer exp;
        input [8*32-1:0] label;
        begin
            if (got == exp) passed = passed + 1;
            else begin
                failed = failed + 1;
                $display("CHECK FAIL %0s: got %0d expected %0d", label, got, exp);
            end
        end
    endtask

    // Wait (at negedges) until pwm equals v, bounded.
    task wait_level;
        input v;
        output found;
        begin
            found = (pwm === v);
            guard = 0;
            while (!found && guard < 64) begin
                @(negedge clk);
                guard = guard + 1;
                found = (pwm === v);
            end
        end
    endtask

    // Measure the next complete high run; returns at the first low sample after it.
    task high_run;
        output integer n;
        output found;
        reg f;
        begin
            n = 0;
            wait_level(1'b0, f);
            if (f) wait_level(1'b1, f);
            if (f) begin
                guard = 0;
                while (pwm === 1'b1 && guard < 64) begin
                    n = n + 1;
                    guard = guard + 1;
                    @(negedge clk);
                end
                if (pwm === 1'b1) f = 1'b0;
            end
            found = f;
        end
    endtask

    initial begin
        repeat (3) @(posedge clk);
        @(negedge clk) rst = 1'b0;

        duty = 4'd3;
        high_run(len, ok); high_run(len, ok);
        for (i = 0; i < 3; i = i + 1) begin
            high_run(len, ok);
            check_eq(ok ? len : -1, 3, "pulse_width.duty3");
        end

        duty = 4'd5;
        high_run(len, ok); high_run(len, ok);
        for (i = 0; i < 3; i = i + 1) begin
            high_run(len, ok);
            check_eq(ok ? len : -1, 5, "pulse_width.duty5");
        end

        duty = 4'd1;
        high_run(len, ok); high_run(len, ok);
        for (i = 0; i < 3; i = i + 1) begin
            high_run(len, ok);
            check_eq(ok ? len : -1, 1, "pulse_width.duty1");
        end

        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = 0;
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end
endmodule
=== END FILE ===
