`timescale 1ns / 1ps
// Repro for bucket B2 (period): successive pwm rising edges must be PERIOD
// clock cycles apart. Rise-to-rise distance is independent of pulse width.
module tb_pwm_period;
    reg        clk = 1'b0;
    reg        rst = 1'b1;
    reg  [3:0] duty = 4'd3;
    wire       pwm;
    integer    passed = 0;
    integer    failed = 0;
    integer    guard;
    integer    gap;
    integer    i;
    reg        ok;
    reg [8*64-1:0] nonce;

    pwm_gen #(.PERIOD(8)) dut (.clk(clk), .rst(rst), .duty(duty), .pwm(pwm));

    always #5 clk = ~clk;

    task check_eq;
        input integer got;
        input integer exp;
        input [8*32-1:0] label;
        begin
            if (got == exp) passed = passed + 1;
            else begin
                failed = failed + 1;
                $display("CHECK FAIL %0s: got %0d expected %0d", label, got, exp);
            end
        end
    endtask

    task wait_level;
        input v;
        output found;
        begin
            found = (pwm === v);
            guard = 0;
            while (!found && guard < 64) begin
                @(negedge clk);
                guard = guard + 1;
                found = (pwm === v);
            end
        end
    endtask

    // Cycles from one pwm rising edge to the next.
    task rise_gap;
        output integer n;
        output found;
        reg f;
        begin
            n = 0;
            wait_level(1'b0, f);
            if (f) wait_level(1'b1, f);
            if (f) begin
                guard = 0;
                while (pwm === 1'b1 && guard < 64) begin
                    n = n + 1; guard = guard + 1; @(negedge clk);
                end
                while (pwm === 1'b0 && guard < 64) begin
                    n = n + 1; guard = guard + 1; @(negedge clk);
                end
                f = (pwm === 1'b1);
            end
            found = f;
        end
    endtask

    initial begin
        repeat (3) @(posedge clk);
        @(negedge clk) rst = 1'b0;

        duty = 4'd3;
        rise_gap(gap, ok);
        for (i = 0; i < 3; i = i + 1) begin
            rise_gap(gap, ok);
            check_eq(ok ? gap : -1, 8, "period.duty3");
        end

        duty = 4'd5;
        rise_gap(gap, ok); rise_gap(gap, ok);
        for (i = 0; i < 3; i = i + 1) begin
            rise_gap(gap, ok);
            check_eq(ok ? gap : -1, 8, "period.duty5");
        end

        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = 0;
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end
endmodule
=== END FILE ===
=== FILE: tb/tb_pwm_duty_update.v ===
`timescale 1ns / 1ps
// Repro for bucket B3 (duty_update): duty is sampled once per period, so a
// change in the middle of a period must not affect that period. Run lengths
// are compared with each other, not with constants, so width/period faults
// do not trip these checks.
module tb_pwm_duty_update;
    reg        clk = 1'b0;
    reg        rst = 1'b1;
    reg  [3:0] duty = 4'd2;
    wire       pwm;
    integer    passed = 0;
    integer    failed = 0;
    integer    guard;
    integer    len;
    integer    h1;
    integer    h2;
    integer    hold;
    integer    rest;
    reg        ok;
    reg        ok1;
    reg        ok2;
    reg [8*64-1:0] nonce;

    pwm_gen #(.PERIOD(8)) dut (.clk(clk), .rst(rst), .duty(duty), .pwm(pwm));

    always #5 clk = ~clk;

    task check_eq;
        input integer got;
        input integer exp;
        input [8*32-1:0] label;
        begin
            if (got == exp) passed = passed + 1;
            else begin
                failed = failed + 1;
                $display("CHECK FAIL %0s: got %0d expected %0d", label, got, exp);
            end
        end
    endtask

    task wait_level;
        input v;
        output found;
        begin
            found = (pwm === v);
            guard = 0;
            while (!found && guard < 64) begin
                @(negedge clk);
                guard = guard + 1;
                found = (pwm === v);
            end
        end
    endtask

    task high_run;
        output integer n;
        output found;
        reg f;
        begin
            n = 0;
            wait_level(1'b0, f);
            if (f) wait_level(1'b1, f);
            if (f) begin
                guard = 0;
                while (pwm === 1'b1 && guard < 64) begin
                    n = n + 1;
                    guard = guard + 1;
                    @(negedge clk);
                end
                if (pwm === 1'b1) f = 1'b0;
            end
            found = f;
        end
    endtask

    initial begin
        repeat (3) @(posedge clk);
        @(negedge clk) rst = 1'b0;

        // Scenario A: raise duty 2 -> 6 while pwm is low in the middle of a period.
        duty = 4'd2;
        high_run(len, ok); high_run(len, ok);
        high_run(hold, ok);            // returns at the first low sample after a pulse
        duty = 4'd6;                   // mid-period change
        high_run(h1, ok1);             // first pulse after the change
        high_run(h2, ok2);             // steady pulse with duty 6
        check_eq((ok && ok1 && ok2) ? h1 : -1, h2, "duty_update.raise_mid_period");

        // Scenario B: lower duty 6 -> 2 during a pulse; that pulse keeps its length.
        wait_level(1'b0, ok);
        if (ok) wait_level(1'b1, ok);  // first high sample of a new pulse
        duty = 4'd2;                   // change after the period's sample point
        rest = 0;
        guard = 0;
        while (ok && pwm === 1'b1 && guard < 64) begin
            rest = rest + 1;
            guard = guard + 1;
            @(negedge clk);
        end
        if (pwm === 1'b1) ok = 1'b0;
        check_eq((ok && ok2) ? rest : -1, h2, "duty_update.lower_mid_pulse");

        // After the change settles, consecutive pulses agree.
        high_run(h1, ok1);
        high_run(h2, ok2);
        check_eq((ok1 && ok2) ? h1 : -1, h2, "duty_update.after_lower");

        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = 0;
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end
endmodule
=== END FILE ===
